                '<td>' + (p.site||'-') + '</td><td><span style="font-size:11px;' + wsColor + '">' + (p.workerStatus||'íŒŒê²¬ì¤‘') + '</span></td>' +
                '<td>' + statusPill(p.safety) + '</td>' + workerScreenCell(p) + '</tr>';
